import{_ as e,o as r,c as o,a3 as t}from"./chunks/framework.Dj4Lt7vj.js";const f=JSON.parse('{"title":"平台支持问题","description":"","frontmatter":{"title":"平台支持问题"},"headers":[],"relativePath":"faq/platforms.md","filePath":"faq/platforms.md","lastUpdated":1787949005000}'),i={name:"faq/platforms.md"};function l(s,a,n,d,h,c){return r(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="平台支持问题" tabindex="-1">平台支持问题 <a class="header-anchor" href="#平台支持问题" aria-label="Permalink to &quot;平台支持问题&quot;">​</a></h1><p>关于平台支持的高频问题。完整的支持矩阵见<a href="/aicare-docs/client/platforms">支持的平台</a>。</p><h2 id="支持哪些平台" tabindex="-1">支持哪些平台？ <a class="header-anchor" href="#支持哪些平台" aria-label="Permalink to &quot;支持哪些平台？&quot;">​</a></h2><p>千牛/淘宝（仅 Windows）、拼多多、京东、抖音、快手、闲鱼。</p><h2 id="为什么千牛只能在-windows-上用" tabindex="-1">为什么千牛只能在 Windows 上用？ <a class="header-anchor" href="#为什么千牛只能在-windows-上用" aria-label="Permalink to &quot;为什么千牛只能在 Windows 上用？&quot;">​</a></h2><p>千牛的 AI 接待和商品学习都依赖 Windows 桌面组件，macOS 上没有对应能力。计划接入千牛/淘宝的商家请准备 Windows 电脑。</p><h2 id="闲鱼为什么不能转人工" tabindex="-1">闲鱼为什么不能转人工？ <a class="header-anchor" href="#闲鱼为什么不能转人工" aria-label="Permalink to &quot;闲鱼为什么不能转人工？&quot;">​</a></h2><p>闲鱼当前不支持转人工。闲鱼店铺的替代做法：</p><ol><li>关注客户端通知。</li><li>每天处理<a href="/aicare-docs/workspace/records">聊天记录</a>里的待跟进会话。</li></ol><h2 id="电脑关机了-ai-还会接待吗" tabindex="-1">电脑关机了 AI 还会接待吗？ <a class="header-anchor" href="#电脑关机了-ai-还会接待吗" aria-label="Permalink to &quot;电脑关机了 AI 还会接待吗？&quot;">​</a></h2><p><strong>不会。</strong> 接待在你的电脑上运行，电脑关机、客户端退出、平台窗口关闭，接待都会停止。这是产品的工作方式——你的店铺账号只在自己电脑上登录。</p><p>晚上无人值守的时段，用<a href="/aicare-docs/solution/general#服务策略">夜间服务模式</a>自动应答并留言跟进。</p><h2 id="一台电脑能带几个店铺" tabindex="-1">一台电脑能带几个店铺？ <a class="header-anchor" href="#一台电脑能带几个店铺" aria-label="Permalink to &quot;一台电脑能带几个店铺？&quot;">​</a></h2><p>电脑本身没有固定的店铺数量限制。套餐限制的是客服账号接入位：每接入一个平台客服账号会占用一个接入位。可用数量以「账单」页当前套餐说明为准，见<a href="/aicare-docs/client/shops">接入店铺和客服账号</a>。</p><h2 id="可以多台电脑同时接待吗" tabindex="-1">可以多台电脑同时接待吗？ <a class="header-anchor" href="#可以多台电脑同时接待吗" aria-label="Permalink to &quot;可以多台电脑同时接待吗？&quot;">​</a></h2><p>可以，同一账号可在多台电脑登录客户端，不同店铺分布在不同电脑上接待。同一个平台客服账号同一时间只在一台电脑上接待。各台电脑的在线状态可以在工作台的「设备」标签页查看。</p><h2 id="平台改版导致接待异常怎么办" tabindex="-1">平台改版导致接待异常怎么办？ <a class="header-anchor" href="#平台改版导致接待异常怎么办" aria-label="Permalink to &quot;平台改版导致接待异常怎么办？&quot;">​</a></h2><p>先把客户端升级到最新版本——平台页面改版的适配修复通过客户端更新发布。升级后仍异常的，<a href="/aicare-docs/client/report">生成错误报告</a>反馈。</p>',18)])])}const m=e(i,[["render",l]]);export{f as __pageData,m as default};
